import{_ as t,o as d,c as a,Q as r}from"./chunks/framework.48927342.js";const m=JSON.parse('{"title":"心理咨询师求职邮件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/emails/12-psychologist-job-application.md","filePath":"zh/more/maltese/practice/emails/12-psychologist-job-application.md"}'),o={name:"zh/more/maltese/practice/emails/12-psychologist-job-application.md"},e=r('<h1 id="心理咨询师求职邮件" tabindex="-1">心理咨询师求职邮件 <a class="header-anchor" href="#心理咨询师求职邮件" aria-label="Permalink to &quot;心理咨询师求职邮件&quot;">​</a></h1><p><strong>场景：</strong> 申请人写信给心理咨询机构，申请心理咨询师职位。</p><h2 id="邮件头部" tabindex="-1">邮件头部 <a class="header-anchor" href="#邮件头部" aria-label="Permalink to &quot;邮件头部&quot;">​</a></h2><p><strong>Lil（收件人 To）：</strong> <a href="mailto:info@clinika.com" target="_blank" rel="noreferrer">info@clinika.com</a><strong>Mingħand（发件人 From）：</strong> [isem]@email.com <strong>Data（日期）：</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett（主题）：</strong> Applikazzjoni ta&#39; xogħol ta&#39; psikologu</p><h2 id="邮件全文" tabindex="-1">邮件全文 <a class="header-anchor" href="#邮件全文" aria-label="Permalink to &quot;邮件全文&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:info@clinika.com" target="_blank" rel="noreferrer">info@clinika.com</a><strong>Mingħand:</strong> [isem]@email.com <strong>Data:</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett:</strong> Applikazzjoni ta&#39; xogħol ta&#39; psikologu</p><p>Għażiż Sinjur / Sinjura,</p><p>Qed nikteb biex napplika għall-impjieg ta&#39; psikologu.</p><p>Għandi lawrja fil-psikoloġija u esperjenza ta&#39; erba&#39; snin.</p><p>Jiena nisma&#39; lin-nies bil-paċenzja u bil-qalb.</p><p>Ngħin lill-klijenti biex jifhmu s-sentimenti tagħhom.</p><p>Nirrispetta l-privatezza ta&#39; kull persuna.</p><p>Nista&#39; naħdem ma&#39; tfal u adulti.</p><p>Noffri appoġġ b&#39;mod professjonali u ħanin.</p><p>Nixtieq noffri l-għajnuna tiegħi lit-tim tagħkom.</p><p>Grazzi talli qiesu l-applikazzjoni tiegħi.</p><p>Nispera li nisma&#39; mingħandkom dalwaqt.</p><p>Tislijiet, [Ismek]</p></blockquote><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:info@clinika.com" target="_blank" rel="noreferrer">info@clinika.com</a></p><p><strong>整句：</strong> 收件人（To）：info@clinika.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Lil</td><td>收件人；给……</td><td>邮件头部&quot;To&quot;的马耳他语标签</td></tr><tr><td><a href="mailto:info@clinika.com" target="_blank" rel="noreferrer">info@clinika.com</a></td><td>邮箱地址</td><td>心理咨询机构的招聘邮箱（示例）</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: [isem]@email.com</p><p><strong>整句：</strong> 发件人（From）：[你的名字]@email.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Mingħand</td><td>发件人；来自……</td><td>邮件头部&quot;From&quot;的马耳他语标签，本义&quot;从……那里&quot;</td></tr><tr><td>[isem]@email.com</td><td>邮箱地址</td><td>你的邮箱占位，请替换为真实邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Data: 15 ta&#39; Ottubru 2026</p><p><strong>整句：</strong> 日期：2026 年 10 月 15 日</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Data</td><td>日期</td><td>邮件头部&quot;Date&quot;；马耳他语日期格式为&quot;日 ta&#39; 月 年&quot;</td></tr><tr><td>15</td><td>十五</td><td>日期中的日</td></tr><tr><td>ta&#39;</td><td>……的</td><td>连接日和月份</td></tr><tr><td>Ottubru</td><td>十月</td><td>月份名</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Applikazzjoni ta&#39; xogħol ta&#39; psikologu</p><p><strong>整句：</strong> 主题：心理咨询师职位申请</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Suġġett</td><td>主题</td><td>邮件头部&quot;Subject&quot;</td></tr><tr><td>Applikazzjoni</td><td>申请</td><td>阴性名词，借词 application</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>xogħol</td><td>工作；职位</td><td>阳性名词</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>psikologu</td><td>心理学家；心理咨询师</td><td>阳性名词，借词 psychologist</td></tr></tbody></table><p><strong>Malti:</strong> Għażiż Sinjur / Sinjura,</p><p><strong>整句：</strong> 亲爱的先生 / 女士：</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għażiż</td><td>亲爱的</td><td>阳性单数形式</td></tr><tr><td>Sinjur</td><td>先生</td><td>阳性名词</td></tr><tr><td>/</td><td>或</td><td>表示二选一</td></tr><tr><td>Sinjura</td><td>女士</td><td>阴性名词</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Qed nikteb biex napplika għall-impjieg ta&#39; psikologu.</p><p><strong>整句：</strong> 我写信是为了申请心理咨询师职位。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Qed</td><td>正在（进行时标记）</td><td>与动词连用表示正在做某事</td></tr><tr><td>nikteb</td><td>我写</td><td>第一人称单数现在时</td></tr><tr><td>biex</td><td>为了</td><td>引出目的状语</td></tr><tr><td>napplika</td><td>我申请</td><td>第一人称单数形式，借词 apply</td></tr><tr><td>għall-impjieg</td><td>申请职位</td><td><code>għal</code> + <code>l-impjieg</code> 缩合</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>psikologu</td><td>心理学家；心理咨询师</td><td>阳性名词，借词 psychologist</td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Għandi lawrja fil-psikoloġija u esperjenza ta&#39; erba&#39; snin.</p><p><strong>整句：</strong> 我有心理学学位和四年的经验。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għandi</td><td>我有</td><td><code>għand</code> 的第一人称单数形式</td></tr><tr><td>lawrja</td><td>学位</td><td>阴性名词，借词 laurea</td></tr><tr><td>fil-psikoloġija</td><td>在心理学方面</td><td><code>f&#39;</code> + <code>il-psikoloġija</code> 缩合</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>esperjenza</td><td>经验</td><td>阴性名词</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>erba&#39;</td><td>四</td><td>数词</td></tr><tr><td>snin</td><td>年</td><td><code>sena</code> 的复数形式</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Jiena nisma&#39; lin-nies bil-paċenzja u bil-qalb.</p><p><strong>整句：</strong> 我耐心而用心地倾听人们。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Jiena</td><td>我</td><td>第一人称单数代词（<code>Jien</code> 的变体）</td></tr><tr><td>nisma&#39;</td><td>我倾听；我听</td><td>第一人称单数形式</td></tr><tr><td>lin-nies</td><td>对人们</td><td><code>li</code> + <code>in-nies</code> 缩合</td></tr><tr><td>bil-paċenzja</td><td>有耐心地</td><td><code>b&#39;</code> + <code>il-paċenzja</code> 缩合</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>bil-qalb</td><td>用心地；真诚地</td><td><code>b&#39;</code> + <code>il-qalb</code>“心”缩合</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Ngħin lill-klijenti biex jifhmu s-sentimenti tagħhom.</p><p><strong>整句：</strong> 我帮助来访者理解自己的感受。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Ngħin</td><td>我帮助</td><td>第一人称单数形式</td></tr><tr><td>lill-klijenti</td><td>给来访者们</td><td><code>li</code> + <code>il-klijenti</code> 缩合</td></tr><tr><td>biex</td><td>为了</td><td>引出目的状语</td></tr><tr><td>jifhmu</td><td>他们理解</td><td>第三人称复数形式</td></tr><tr><td>s-sentimenti</td><td>感受</td><td><code>sentiment</code> 的复数，带定冠词</td></tr><tr><td>tagħhom</td><td>他们的</td><td>复数所有格代词</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Nirrispetta l-privatezza ta&#39; kull persuna.</p><p><strong>整句：</strong> 我尊重每个人的隐私。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nirrispetta</td><td>我尊重</td><td>第一人称单数形式，借词 respect</td></tr><tr><td>l-privatezza</td><td>隐私</td><td>阴性名词，带定冠词</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>kull</td><td>每一个</td><td>限定词</td></tr><tr><td>persuna</td><td>人</td><td>阴性名词</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Nista&#39; naħdem ma&#39; tfal u adulti.</p><p><strong>整句：</strong> 我可以与儿童和成人一起工作。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nista&#39;</td><td>我能</td><td>第一人称单数形式</td></tr><tr><td>naħdem</td><td>我工作</td><td>第一人称单数现在时</td></tr><tr><td>ma&#39;</td><td>和；与</td><td>介词</td></tr><tr><td>tfal</td><td>儿童</td><td><code>tifel/tifla</code> 的复数形式</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>adulti</td><td>成年人</td><td><code>adult</code> 的复数形式，借词 adult</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Noffri appoġġ b&#39;mod professjonali u ħanin.</p><p><strong>整句：</strong> 我以专业而温和的方式提供支持。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Noffri</td><td>我提供</td><td>第一人称单数形式</td></tr><tr><td>appoġġ</td><td>支持</td><td>阳性名词</td></tr><tr><td>b&#39;mod</td><td>以……方式</td><td><code>b&#39;</code> + <code>mod</code>“方式”</td></tr><tr><td>professjonali</td><td>专业的</td><td>形容词，借词 professional</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>ħanin</td><td>温和的；慈悲的</td><td>形容词</td></tr></tbody></table><h3 id="_8" tabindex="-1">8. <a class="header-anchor" href="#_8" aria-label="Permalink to &quot;8.&quot;">​</a></h3><p><strong>Malti:</strong> Nixtieq noffri l-għajnuna tiegħi lit-tim tagħkom.</p><p><strong>整句：</strong> 我希望为你们的团队贡献我的帮助。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nixtieq</td><td>我想要；我希望</td><td>礼貌表达愿望</td></tr><tr><td>noffri</td><td>我提供</td><td>第一人称单数形式</td></tr><tr><td>l-għajnuna</td><td>帮助</td><td>阴性名词，带定冠词</td></tr><tr><td>tiegħi</td><td>我的</td><td>所有格代词</td></tr><tr><td>lit-tim</td><td>给团队</td><td><code>li</code> + <code>it-tim</code> 缩合</td></tr><tr><td>tagħkom</td><td>你们的</td><td>复数所有格代词</td></tr></tbody></table><h3 id="_9" tabindex="-1">9. <a class="header-anchor" href="#_9" aria-label="Permalink to &quot;9.&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi talli qiesu l-applikazzjoni tiegħi.</p><p><strong>整句：</strong> 感谢你们考虑我的申请。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Grazzi</td><td>谢谢</td><td>礼貌用语</td></tr><tr><td>talli</td><td>因为（你们）……</td><td>引出原因的书面表达</td></tr><tr><td>qiesu</td><td>他们考虑了</td><td><code>qies</code> 的第三人称复数过去时</td></tr><tr><td>l-applikazzjoni</td><td>申请</td><td>阴性名词，带定冠词</td></tr><tr><td>tiegħi</td><td>我的</td><td>所有格代词</td></tr></tbody></table><h3 id="_10" tabindex="-1">10. <a class="header-anchor" href="#_10" aria-label="Permalink to &quot;10.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li nisma&#39; mingħandkom dalwaqt.</p><p><strong>整句：</strong> 我希望很快收到你们的回复。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nispera</td><td>我希望</td><td>第一人称单数形式</td></tr><tr><td>li</td><td>……；引出从句</td><td>连词</td></tr><tr><td>nisma&#39;</td><td>我听到；收到消息</td><td>第一人称单数形式</td></tr><tr><td>mingħandkom</td><td>从你们那里</td><td><code>mingħand</code> + <code>-kom</code>“你们”</td></tr><tr><td>dalwaqt</td><td>很快</td><td>副词</td></tr></tbody></table><p><strong>Malti:</strong> Tislijiet, [Ismek]</p><p><strong>整句：</strong> 此致敬意，[你的名字]（正式邮件落款）。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tislijiet</td><td>此致敬意；致以问候</td><td>正式邮件/信件落款用语，本义&quot;问候/致意&quot;</td></tr><tr><td>Ismek</td><td>你的名字</td><td><code>isem</code>“名字” + <code>-ek</code>“你的”；请替换为真实姓名</td></tr></tbody></table>',65),i=[e];function n(l,h,s,p,c,g){return d(),a("div",null,i)}const u=t(o,[["render",n]]);export{m as __pageData,u as default};
